create or replace TABLE KFL_PRODUCTION.DBP_DATA.AS_FOOD_DET_1 cluster by (MANDANT_ID)(
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Artikelnummer im DWH',
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_1 im DWH',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup_1 ID wird verwendet für Beziehung Lager zu Verteilzentrum',
	DAT_AUSLISTUNG DATE NOT NULL COMMENT 'Das Datum der Auslistung aus dem Quellfeld aldat',
	KJWO NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Kalenderjahreswoche. Format JJJJWW',
	PHASE_WO NUMBER(38,0) NOT NULL COMMENT 'Kalenderjahreswoche. Format JJJJWW. Wird aus dem Quellfeld alweek befüllt. Referenz zur Tabelle woche_1',
	WRG_ID VARCHAR(3) COLLATE 'en-ci' COMMENT 'Kurzbezeichnung der Waehrung, z.Bsp. CZK, EUR',
	ERL_KZ VARCHAR(1) NOT NULL COMMENT 'Erledigtkennzeichen aus SAP; Quelle: zrs_vrdata/erlkz',
	DAT_FINAL DATE COMMENT 'Datum Laufzeitende aus dem Quellfeld final',
	AS_FINAL_STATUS_ID NUMBER(38,0) COMMENT 'Klassifizierung der Datensätze nach Status_1 des ausgelisteten Sortiments nachdem dat_final vorhanden ist. 0 = default / Kein Restbestand ; 1 = Absatz, trotz Finaldatum; 2 = Finaldatum, aber keine ERL-KZ = D (Abschrift)',
	PHASE_ID NUMBER(38,0) NOT NULL COMMENT 'ID ergibt sich aus ALWEEK (ID = 0), WEEK01 (ID = 1), usw',
	PHASE_VK_BRUTTO NUMBER(9,2) NOT NULL DEFAULT 0 COMMENT 'Verkaufspreis brutto aus dem Quellfeld vkpr01,vkpr02 usw. (VK_1 der jeweiligen Phase) - Wert bezieht sich auf komplette Phase',
	PHASE_VK_NETTO NUMBER(9,2) NOT NULL COMMENT 'wird aus phase_vk_brutto errechnet (reduziert um MwSt-Betrag) - Wert bezieht sich auf komplette Phase',
	MENGE_TOTALABSCHRIFT NUMBER(18,3) NOT NULL COMMENT 'Menge der Totalabschriften (für DE AKZ = 122; KMO aus DWH-Tabelle marktabschriften_1)',
	BETRAG_TOTALABSCHRIFT_NETTO NUMBER(18,4) NOT NULL DEFAULT 0 COMMENT 'Betrag netto der Totalabschriften (für DE AKZ = 122; KMO aus DWH-Tabelle marktabschriften_1)',
	MENGE_PREISABSCHRIFT NUMBER(18,3) NOT NULL COMMENT 'Menge der Preisabschriften (für DE AKZ = 22; KMO aus DWH-Tabelle marktabschriften_1)',
	BETRAG_PREISABSCHRIFT_NETTO NUMBER(18,4) NOT NULL DEFAULT 0 COMMENT 'Betrag netto der Preisabschriften (für DE AKZ = 22; KMO aus DWH-Tabelle marktabschriften_1)',
	MENGE_ENDBESTAND_PHASE NUMBER(18,3) NOT NULL COMMENT 'Endbestand pro Phasenende - Wert bezieht sich nicht auf KJWO, sondern Ende der Phase',
	MENGE_ENDBESTAND NUMBER(38,3) COMMENT 'Endbestand pro Kalenderwoche - aus DWH-Tabelle marktbestand_erp. In der laufenden Woche_1 beinhaltet die Spalte den Bestand des Vortages, in allen vergangenen Kalenderwochen, den Endbestand dieser KJWO.',
	MENGE_ABSATZ NUMBER(18,3) NOT NULL COMMENT 'Menge des Absatz - aus DWH-Tabelle artbew_1 (dient zum tagesgenauen Auslesen der Absaetze fuer die laenderspezifischen Phasenzeitraeume)',
	UMSATZ_NETTO NUMBER(18,4) NOT NULL DEFAULT 0 COMMENT 'Umsatz vermindert um den Mehrwertsteuerbetrag - aus DWH-Tabelle artbew_1 (dient zum tagesgenauen Auslesen der Umsaetze fuer die laenderspezifischen Phasenzeiträume)',
	BETRAG_EK_NETTONETTO NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Summe der Einkaufspreise nettonetto (Bedeutung vgl. Kalkulationsschema). - Wert aus DWH-Tabelle artbew_wo_sum.',
	BETRAG_EK_MEP NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Summe der Markteinstandspreise (Bedeutung vgl. Kalkulationsschema). - aus DWH-Tabelle artbew_wo_sum.',
	BETRAG_EINSTANDSPREIS NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Summe der Kaufland Einstandspreis (Bedeutung vgl. Kalkulationsschema). - aus DWH-Tabelle artbew_wo_sum.',
	BETRAG_LOGKOSTENZUSCHLAG NUMBER(38,4) COMMENT 'Summe der Logistikkostenzuschläge (ein kalkulierter Wert für die Zentrallagerkosten, der bei zentraler Lieferung Bestandteil einiger Einstandspreise ist). -aus DWH-Tabelle artbew_wo_sum.',
	BETRAG_EK_MEP_VOR_FWU NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Summe der Markteinstandspreise vor Festwertumlage: Mit Einführung der Festwertumlage in KMO braucht es einen \"alten\" EK3Netto ohne die Festwertumlage als Vergleichswert. Dieser Wert wird aus SAP über ZEKP.MEPOL geliefert.- aus DWH-Tabelle artbew_wo_sum.',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	constraint PK_AS_FOOD_DET primary key (ART_ID, MANDANT_ID, NB_ID, WUP_ID, DAT_AUSLISTUNG, KJWO)
)COMMENT='AIS - Auslistungs-Schema Detailtabelle aus der Quelltabelle zrs_rvdata'
;